Shader.VertexShader:
in vec3 a_position;
in vec2 a_texcoord0;
out vec2 v_texcoord0;
uniform mat4 u_modelViewProjectionTransform;
void main() {
  v_texcoord0 = a_texcoord0;
  gl_Position = u_modelViewProjectionTransform * vec4(a_position, 1.0);
}

Shader.FragmentShader:
// IC_Glass: smoked glass: vertical light falloff and a diagonal specular sheen band
// Mirrors the Blender node group "IC_Glass"; uniform names are its input names.
// ORCA prepends the #version line and declares the FragColor output; colour
// uniforms are vec4 display (sRGB) values and only .rgb is used.
in vec2 v_texcoord0;

void main() {
  float u=v_texcoord0.x, v=v_texcoord0.y;
  float band=Sheen*exp(-pow((u*.55+v-SheenPos)/SheenWidth,2.0));
  vec3 color=mix(Tint.rgb,TopTint.rgb,v)+vec3(.75,.88,1.0)*band;
  FragColor=vec4(color,clamp(Density+band*.4,0.0,1.0));
}
